    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da LSI: as famílias são selecionadas pelos Accommodation Officers da própria escola e visitadas com regularidade. Você pode escolher quarto individual (ou twin, quando duas pessoas reservam para o mesmo período) com café da manhã ou meia pensão. Roupa de cama e toalhas são fornecidas e trocadas semanalmente e o anfitrião oferece pelo menos uma lavagem de roupa por semana sem custo. Quem reserva só com café da manhã normalmente não tem acesso à cozinha. Há a opção Executive, com banheiro privativo (ensuite ou de uso exclusivo), mediante suplemento. Em Cambridge, a LSI administra sua própria rede de famílias dentro de um raio de até 30 minutos da escola; as chegadas são aos sábados ou domingos, entre 9h e 22h (em julho e agosto, apenas aos domingos). Um passe de ônibus urbano ilimitado custa cerca de 18 libras por semana. Menores de 18 anos precisam reservar meia pensão. Nesta opção o quarto é duplo/twin (para quem viaja acompanhado ou dividido com outro estudante do mesmo gênero) e o banheiro é compartilhado. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta.</p><p>Suplementos e condições: Suplemento de alta temporada: GBP 45/semana (14/jun a 23/ago); Suplemento dieta especial: GBP 50/semana; Outro suplemento: GBP 60.</p><p>Suplementos da casa de família em LSI Cambridge, por pessoa por semana: verão de 14/jun a 23/ago £45; Natal (fins de semana de 26-27/dez e 2-3/jan) £60; dieta especial £40 com café da manhã e £50 com meia pensão; menores de 18 anos £20. Taxa de colocação da acomodação não cobrada. Taxa de inscrição da escola £95, envio de documentos por courier £100, seguro-saúde £14 por semana, transfer do aeroporto £220 somente ida. Chegadas e saídas de sábado a sábado ou de domingo a domingo. Os preços da acomodação podem mudar ao longo do ano — confirme com a LSI Cambridge na hora da reserva. Fonte: LSI Prices and Dates 2026.</p>','["Famílias Selecionadas e Visitadas pela Escola", "Roupa de Cama e Toalhas Trocadas Semanalmente", "1 Lavagem de Roupa por Semana Inclusa", "Quarto Individual ou Twin", "Imersão Cultural", "Prática Diária de Inglês", "Opção Executive com Banheiro Privativo", "Chegadas aos Sábados ou Domingos", "Quarto Duplo/Twin", "Banheiro Compartilhado", "Meia Pensão", "Ideal para quem quer imersão cultural e prática diária de inglês", "Ideal para quem prefere ter refeições resolvidas em casa", "Ideal para quem viaja sozinho e quer apoio de anfitriões locais", "Ideal para quem busca bom custo-benefício com serviços inclusos", "Ideal para quem viaja acompanhado ou quer dividir custos", "Ideal para quem gosta de socializar e não se importa em dividir espaços", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem quer cozinhar livremente (sobretudo no regime só com café da manhã)", "Menos indicado para quem precisa morar a poucos minutos da escola", "Menos indicado para quem quer liberdade total de horários e visitas", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem precisa de privacidade e silêncio", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
